using System;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class WindDesignForm {
 DataGridView staadProfile,staadNet;
 static DataGridView StaadGrid(params string[] headers){var grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.AllCells};foreach(string header in headers)grid.Columns.Add(header,header);grid.CellFormatting+=(s,e)=>{if(e.Value is double){double value=(double)e.Value;e.Value=WindTin.Finite(value)?value.ToString("0.######",CultureInfo.InvariantCulture):"Unresolved";e.FormattingApplied=true;}};GridAppearance.Apply(grid);return grid;}
 static string GridText(DataGridView grid,string separator){Func<string,string> quote=value=>separator==","?"\""+(value??"").Replace("\"","\"\"")+"\"":(value??"").Replace("\t"," ").Replace("\r"," ").Replace("\n"," ");var b=new StringBuilder();b.AppendLine(string.Join(separator,grid.Columns.Cast<DataGridViewColumn>().Select(c=>quote(c.HeaderText))));foreach(DataGridViewRow row in grid.Rows)if(!row.IsNewRow)b.AppendLine(string.Join(separator,row.Cells.Cast<DataGridViewCell>().Select(c=>quote(Convert.ToString(c.Value,CultureInfo.InvariantCulture)))));return b.ToString();}
 void AddStaadWindPage(){var root=new TabPage("STAAD Wind Input");var nested=new NavigationTabs{Dock=DockStyle.Fill};staadProfile=StaadGrid("Wind from","Height above ground (m)","qz (kPa = kN/m2)","Kz","Kzt(z)","Exposure");staadNet=StaadGrid("Wind from / axis","Surface","Load case","Height (m)","Net pressure p (kPa)","q / qh basis","G","Cp","GCpi");string[] titles={"Height–pressure profile (qz)","Net wall & roof pressures"};var grids=new[]{staadProfile,staadNet};for(int i=0;i<2;i++){var grid=grids[i];var page=new TabPage(titles[i]);var commands=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true};var copy=new Button{Text="Copy table",AutoSize=true};copy.Click+=(s,e)=>Clipboard.SetText(GridText(grid,"\t"));var export=new Button{Text="Export CSV",AutoSize=true};export.Click+=(s,e)=>{using(var dialog=new SaveFileDialog{Filter="CSV table|*.csv",FileName=grid==staadProfile?"STAAD-Wind-Height-Pressure.csv":"STAAD-Net-Surface-Pressures.csv"})if(dialog.ShowDialog(this)==DialogResult.OK)File.WriteAllText(dialog.FileName,GridText(grid,","),new UTF8Encoding(true));};Action refresh=()=>{bool ready=grid.Rows.Count>0&&!grid.Rows.Cast<DataGridViewRow>().Any(row=>row.Cells.Cast<DataGridViewCell>().Any(cell=>cell.Value==null||cell.Value is double&&!WindTin.Finite((double)cell.Value)||cell.Value is string&&((string)cell.Value).Contains("Unresolved")));copy.Enabled=export.Enabled=ready;};grid.RowsAdded+=(s,e)=>refresh();grid.RowsRemoved+=(s,e)=>refresh();refresh();commands.Controls.AddRange(new Control[]{copy,export});var note=new Label{Dock=DockStyle.Bottom,Height=85,Padding=new Padding(10),Text=i==0?"Velocity-pressure profile qz by wind direction, including eave, mean roof and apex heights. Units: m and kN/m². qz is not net surface pressure; coordinate direction and STAAD wind-generation coefficients must be checked. Do not apply G/Cp twice.":"Net pressures include G, external Cp and the signed internal GCpi case. Positive is toward the surface, negative away. Assign correct plate/member normals and tributary areas in STAAD; do not use these values as a second wind-definition intensity."};page.Controls.Add(grid);page.Controls.Add(note);page.Controls.Add(commands);nested.TabPages.Add(page);}root.Controls.Add(nested);AddResultPage(root);}
 void UpdateStaadWindInputs(List<WindDirection> directions,double speed){if(staadProfile==null)return;staadProfile.Rows.Clear();staadNet.Rows.Clear();WindBuildingInput building;if(directions==null||!TryBuildingGeometry(out building))return;foreach(var row in WindStaadInput.Profile(building,speed,Number("Kd"),directions))staadProfile.Rows.Add(row.Direction,row.Height,row.Qz,row.Kz,row.Kzt,row.Exposure);if(!BuildingEnabled)return;try{foreach(var row in PressureRows(Building()))staadNet.Rows.Add(row.Direction,row.Surface,row.Case,F(row.Z),F(row.P),F(row.Q)+" / "+F(row.Qh),F(row.G),F(row.Cp),F(row.GCpi));}catch(Exception error){staadNet.Rows.Add("Unresolved",error.Message);}}
}
}
